returnValue.propertySchema:
{
	"name":
	{
		"description": "The display name for this emitter in the System."
	},
	"id":
	{
		"title": "Guid",
		"description": "The id of this emitter handle.",
		"type": "object",
		"properties":
		{
			"a":
			{
				"type": "integer"
			},
			"b":
			{
				"type": "integer"
			},
			"c":
			{
				"type": "integer"
			},
			"d":
			{
				"type": "integer"
			}
		},
		"required": [
			"a",
			"b",
			"c",
			"d"
		]
	},
	"idName":
	{
		"type": "string",
		"description": "HACK!  Data sets used to use the emitter name, but this isn't guaranteed to be unique.  This is a temporary hack\nto allow the data sets to continue work with using names, but that code needs to be refactored to use the id defined here."
	},
	"bIsEnabled":
	{
		"description": "Whether or not this emitter is enabled within the System.  Disabled emitters aren't simulated."
	},
	"emitterMode":
	{
	},
	"bIsolated":
	{
	},
	"versionedInstance":
	{
		"description": "The copied instance of the emitter this handle references."
	},
	"statelessEmitter":
	{
		"description": "-TODO:Stateless: Should we return a bass class here / have a factory method to generate the runtime instance?"
	},
	"version":
	{
	},
	"versionChangeDescription":
	{
		"description": "What changed in this version compared to the last? Displayed to the user when upgrading to a new script version."
	},
	"updateScriptExecution":
	{
		"description": "Reference to a python script that is executed when the user updates from a previous version to this version."
	},
	"pythonUpdateScript":
	{
		"description": "Python script to run when updating to this script version."
	},
	"scriptAsset":
	{
		"description": "Asset reference to a python script to run when updating to this script version."
	},
	"updateUtilityClass":
	{
	},
	"bDeprecated":
	{
		"description": "If this emitter version is no longer meant to be used, this option should be set."
	},
	"deprecationMessage":
	{
		"description": "Message to display when the script is deprecated."
	},
	"bLocalSpace":
	{
		"type": "boolean",
		"description": "Toggles whether or not the particles within this emitter are relative to the emitter origin or in global space."
	},
	"bDeterminism":
	{
		"type": "boolean",
		"description": "Toggles whether to globally make the random number generator be deterministic or non-deterministic. Any random calculation that is set to the emitter defaults will inherit this value. It is still possible to tweak individual random to be deterministic or not. In this case deterministic means that it will return the same results for the same configuration of the emitter as long as delta time is not variable. Any changes to the emitter's individual scripts will adjust the results."
	},
	"randomSeed":
	{
		"type": "integer",
		"description": "An emitter-based seed for the deterministic random number generator."
	},
	"interpolatedSpawnMode":
	{
		"type": "string",
		"title": "ENiagaraInterpolatedSpawnMode",
		"enum": [
			"NoInterpolation",
			"RunUpdateScript",
			"Interpolation"
		],
		"description": "This defines if newly spawned particles run only the spawn script on the first frame or both spawn and update with optional parameter interpolation."
	},
	"bGpuAlwaysRunParticleUpdateScript":
	{
		"description": "GPU scripts were incorrectly running both particle spawn & update, CPU only runs spawn when interpolated spawning is disabled.\nThis flag allows backwards compatability so content does not change post the fix."
	},
	"simTarget":
	{
		"type": "string",
		"title": "ENiagaraSimTarget",
		"enum": [
			"CPUSim",
			"GPUComputeSim"
		]
	},
	"importance":
	{
		"type": "string",
		"title": "ENiagaraEmitterImportance",
		"enum": [
			"Critical",
			"Normal",
			"Low"
		],
		"description": "Determines how important this emitter is for the runtime and rendering of the system.\nAn emitter with low priority does not block system execution or other emitters from rendering if its own materials are not yet done compiling.\nA critical emitter can block both activation and rendering of the system until it's ready.\nSee also: readiness settings in the effect type."
	},
	"calculateBoundsMode":
	{
		"type": "string",
		"title": "ENiagaraEmitterCalculateBoundMode",
		"enum": [
			"Dynamic",
			"Fixed",
			"Programmable"
		],
		"description": "How should we calculate bounds for the emitter.\nNote: If this is greyed out it means fixed bounds are enabled in the System Properties and these bounds are therefore ignored."
	},
	"fixedBounds":
	{
		"title": "Box",
		"description": "The fixed bounding box value. CalculateBoundsMode is the condition whether the fixed bounds can be edited.\nNote: If this is greyed out it means fixed bounds are enabled in the System Properties and these bounds are therefore ignored.",
		"type": "object",
		"properties":
		{
			"min":
			{
				"title": "Vector",
				"type": "object",
				"properties":
				{
					"x":
					{
						"type": "number"
					},
					"y":
					{
						"type": "number"
					},
					"z":
					{
						"type": "number"
					}
				},
				"required": [
					"x",
					"y",
					"z"
				]
			},
			"max":
			{
				"title": "Vector",
				"type": "object",
				"properties":
				{
					"x":
					{
						"type": "number"
					},
					"y":
					{
						"type": "number"
					},
					"z":
					{
						"type": "number"
					}
				},
				"required": [
					"x",
					"y",
					"z"
				]
			},
			"isValid":
			{
				"type": "boolean"
			}
		},
		"required": [
			"min",
			"max",
			"isValid"
		]
	},
	"bRequiresPersistentIds":
	{
		"type": "boolean",
		"description": "Creates a stable Identifier (Particles.ID) which does not vary from frame to frame. This comes at a small memory and performance cost. This allows external objects to track the same particle over multiple frames. Particle arrays are tightly packed and a particle's actual index in the array may change from frame to frame. This optionally lets you use a lookup table to track a particle by index in the lookup table."
	},
	"eventHandlerScriptProps":
	{
	},
	"platforms":
	{
		"title": "NiagaraPlatformSet",
		"type": "object",
		"properties":
		{
			"deviceProfileStates":
			{
				"type": "array",
				"items":
				{
				},
				"description": "States of specific device profiles we've set."
			},
			"cVarConditions":
			{
				"type": "array",
				"items":
				{
				},
				"description": "Set of CVars values we require for this platform set to be enabled. If any of the linked CVars don't have the required values then this platform set will not be enabled."
			},
			"qualityLevelMask":
			{
				"type": "integer",
				"description": "Mask defining which effects qualities this set matches."
			}
		},
		"required": [
			"deviceProfileStates",
			"cVarConditions",
			"qualityLevelMask"
		]
	},
	"scalabilityOverrides":
	{
		"title": "NiagaraEmitterScalabilityOverrides",
		"type": "object",
		"properties":
		{
			"overrides":
			{
				"type": "array",
				"items":
				{
				}
			}
		},
		"required": [
			"overrides"
		]
	},
	"maxGPUParticlesSpawnPerFrame":
	{
		"type": "integer",
		"description": "An override on the max number of GPU particles we expect to spawn in a single frame. A value of 0 means it'll use fx.MaxNiagaraGPUParticlesSpawnPerFrame."
	},
	"allocationMode":
	{
		"type": "string",
		"title": "EParticleAllocationMode",
		"enum": [
			"AutomaticEstimate",
			"ManualEstimate",
			"FixedCount"
		],
		"description": "The emitter needs to allocate memory for the particles each tick.\nTo prevent reallocations, the emitter should allocate as much memory as is needed for the max particle count.\nThis setting controls if the allocation size should be automatically determined or manually entered."
	},
	"preAllocationCount":
	{
		"type": "integer",
		"description": "The emitter will allocate at least this many particles on it's first tick.\nThis can aid performance by avoiding many allocations as an emitter ramps up to it's max size."
	},
	"emitterDependencies":
	{
		"type": "array",
		"items":
		{
		},
		"description": "List of emitter dependencies to use when calculating the execution order for emitter particle scripts.\nThis is generally only required when you are using advanced features, such as reading / writing to a data interface in different emitters\nand need to ensure the emitters can not run concurrently with one another, either on the CPU or the GPU."
	},
	"updateScriptProps":
	{
	},
	"spawnScriptProps":
	{
	},
	"rendererBindings":
	{
	},
	"rendererBindingsExternalObjects":
	{
	},
	"resolvedDIBindings":
	{
	},
	"attributesToPreserve":
	{
		"type": "array",
		"items":
		{
		},
		"description": "An allow list of Particle attributes (e.g. \"Particle.Position\" or \"Particle.Age\") that will not be removed from the DataSet  even if they aren't read by the VM.\n          Used in conjunction with UNiagaraSystem::bTrimAttributes"
	},
	"addEmitterDefaultViewState":
	{
		"type": "string",
		"title": "ENiagaraEmitterDefaultSummaryState",
		"enum": [
			"Default",
			"Summary"
		],
		"description": "This determines how emitters will be added to a system by default. If summary view is setup, consider setting this to 'Summary'."
	},
	"emitterSpawnScriptProps":
	{
	},
	"emitterUpdateScriptProps":
	{
	},
	"graphSource":
	{
		"description": "'Source' data/graphs for the scripts used by this emitter."
	},
	"scratchPads":
	{
	},
	"parentScratchPads":
	{
	},
	"versionedParent":
	{
	},
	"versionedParentAtLastMerge":
	{
	},
	"rendererProperties":
	{
	},
	"simulationStages":
	{
	},
	"simStageExecutionLoops":
	{
	},
	"simStageExecutionLoopEditorData":
	{
		"type": "array",
		"items":
		{
		}
	},
	"gPUComputeScript":
	{
	},
	"sharedEventGeneratorIds":
	{
	},
	"currentScalabilitySettings":
	{
	},
	"editorData":
	{
		"description": "Data used by the editor to maintain UI state etc.."
	},
	"editorParameters":
	{
		"description": "Wrapper for editor only parameters."
	}
}
